<?php
declare(strict_types=1);require_once __DIR__.'/error_bootstrap.php';ini_set('session.cookie_httponly','1');ini_set('session.cookie_samesite','Strict');if(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')ini_set('session.cookie_secure','1');session_start();date_default_timezone_set('Asia/Tehran');header('Cache-Control:no-store,private');
if(!file_exists(__DIR__.'/config.php')){header('Location:install.php');exit;}$c=require __DIR__.'/config.php';
try{$pdo=new PDO('mysql:host='.$c['db_host'].';dbname='.$c['db_name'].';charset=utf8mb4',$c['db_user'],$c['db_pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);require_once __DIR__.'/schema.php';ensure_product_schema($pdo);require_once __DIR__.'/admin_auth.php';ts_admin_schema($pdo);}catch(Throwable $e){ts_log_internal($e,'SYS-101');ts_html_fail('SYS-101',503,'index.php');}
$me=ts_require_roles($pdo,['owner','manager']);function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}function token(){if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(24));return $_SESSION['csrf'];}$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($_SESSION['csrf']??'',$_POST['csrf']??'')){ts_html_fail('REQ-102',419,'index.php');}$id=max(0,(int)($_POST['id']??0));$price=max(0,(int)($_POST['price']??0));$stock=max(0,(int)($_POST['stock']??0));if($id){$pdo->prepare('UPDATE products SET price=?,stock=?,updated_at=NOW() WHERE id=? AND active=1')->execute([$price,$stock,$id]);ts_audit($pdo,'quick_product_update','product='.$id.' price='.$price.' stock='.$stock);$msg='قیمت و موجودی ذخیره شد.';}}
$q=trim((string)($_GET['q']??''));$filter=(string)($_GET['filter']??'all');$page=max(1,(int)($_GET['page']??1));$per=50;$where=['active=1'];$params=[];
if($q!==''){$where[]='(name LIKE ? OR barcode LIKE ? OR brand LIKE ? OR pyramid_code2 LIKE ?)';for($i=0;$i<4;$i++)$params[]='%'.$q.'%';}
if($filter==='out')$where[]='stock=0';elseif($filter==='low')$where[]='stock BETWEEN 1 AND 3';elseif($filter==='price0')$where[]='price=0';elseif($filter==='noimage')$where[]="(image_path IS NULL OR image_path='')";elseif($filter==='internal')$where[]='pyramid_barcode_generated=1';
$ws=implode(' AND ',$where);$st=$pdo->prepare('SELECT COUNT(*) FROM products WHERE '.$ws);$st->execute($params);$total=(int)$st->fetchColumn();$pages=max(1,(int)ceil($total/$per));$page=min($page,$pages);$offset=($page-1)*$per;
$sql='SELECT id,name,brand,quantity_label,barcode,pyramid_code2,pyramid_barcode_generated,image_path,price,stock,category FROM products WHERE '.$ws.' ORDER BY name LIMIT '.$per.' OFFSET '.$offset;$st=$pdo->prepare($sql);$st->execute($params);$products=$st->fetchAll();
function urlq(array $x): string {return '?'.http_build_query(array_filter($x,fn($v)=>$v!==''&&$v!==null));}
?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>مدیریت کالاها</title><link rel="stylesheet" href="assets/style.css"><style>.wrap{max-width:1100px;margin:20px auto;padding:0 12px}.filters{display:flex;gap:7px;overflow:auto;margin:10px 0}.filters a{white-space:nowrap;background:#fff;border:1px solid #e4ece5;border-radius:999px;padding:8px 11px}.filters a.on{background:#11823b;color:#fff}.prod{display:grid;grid-template-columns:60px 1fr 170px auto;gap:10px;align-items:center;background:#fff;border:1px solid #e5ece6;border-radius:14px;padding:10px;margin:8px 0}.prod img{width:55px;height:55px;object-fit:contain}.quick{display:flex;gap:6px;align-items:center}.quick input{width:105px}.pages{display:flex;gap:7px;justify-content:center;margin:18px 0}.pages a{padding:8px 12px;background:#fff;border:1px solid #ddd;border-radius:9px}@media(max-width:720px){.prod{grid-template-columns:50px 1fr}.prod img{width:46px;height:46px}.prod>.codes{grid-column:1/-1}.quick{grid-column:1/-1}.quick input{width:100%}}</style></head><body><header class="top"><a class="brand" href="admin.php"><span class="logo">📦</span><span><b>مدیریت کالاها</b><small>جستجو، فیلتر و ویرایش سریع</small></span></a><a class="btn pale" href="admin.php">مدیریت اصلی</a></header><main class="wrap"><?php if($msg):?><div class="success"><?=e($msg)?></div><?php endif;?><form class="search"><input name="q" value="<?=e($q)?>" placeholder="نام، برند، بارکد یا Code2"><input type="hidden" name="filter" value="<?=e($filter)?>"><button class="btn">جستجو</button></form><div class="filters"><?php foreach(['all'=>'همه','low'=>'رو به اتمام','out'=>'ناموجود','price0'=>'بدون قیمت','noimage'=>'بدون عکس','internal'=>'بارکد داخلی'] as $k=>$v):?><a class="<?=$filter===$k?'on':''?>" href="<?=e(urlq(['q'=>$q,'filter'=>$k]))?>"><?=e($v)?></a><?php endforeach;?></div><div class="muted"><?=number_format($total)?> کالا · صفحه <?=$page?> از <?=$pages?></div><?php foreach($products as $p):?><div class="prod"><?php if($p['image_path']):?><img src="<?=e($p['image_path'])?>" alt=""><?php else:?><div style="font-size:35px">🛒</div><?php endif;?><div><b><?=e($p['name'])?></b><div class="muted"><?=e(trim(($p['brand']??'').' '.($p['quantity_label']??'')))?> · <?=e($p['category'])?></div><a href="admin.php?edit=<?=(int)$p['id']?>#add">ویرایش کامل</a></div><div class="codes"><code><?=e($p['barcode']?:'—')?></code><div class="muted">Code2: <?=e($p['pyramid_code2']?:'—')?> <?=$p['pyramid_barcode_generated']?'· داخلی':''?></div></div><form method="post" class="quick"><input type="hidden" name="csrf" value="<?=e(token())?>"><input type="hidden" name="id" value="<?=(int)$p['id']?>"><label>قیمت<input type="number" name="price" min="0" value="<?=(int)$p['price']?>"></label><label>موجودی<input type="number" name="stock" min="0" value="<?=(int)$p['stock']?>"></label><button class="btn">ذخیره</button></form></div><?php endforeach;?><div class="pages"><?php if($page>1):?><a href="<?=e(urlq(['q'=>$q,'filter'=>$filter,'page'=>$page-1]))?>">قبلی</a><?php endif;?><?php if($page<$pages):?><a href="<?=e(urlq(['q'=>$q,'filter'=>$filter,'page'=>$page+1]))?>">بعدی</a><?php endif;?></div></main></body></html>
